.btn {
    border-radius: 20px 0;
    color: $white;
    transition: all .5s;
    font-size: 1.125rem;
    font-weight: 500;
    padding: 8px 10px;

    @include media-breakpoint-down(md){
        font-size: 1rem;
    }

    &:hover {
        background-color: #fff;
        color: $primary;
    }

    &:focus{
        border-color: blue !important;
    }

    @each $color, $value in $theme-colors {
        &-#{$color} {
            border: 1px solid $value;

            i{
                margin-right: 5px;
            }

            &:hover {
                color: $value;
            }
        }
    }
}